import{_ as t,o as e,c as r,a2 as d}from"./chunks/framework.D3fmyz3M.js";const p=JSON.parse('{"title":"何时用，何时不用","description":"用五个信号判断是否该引入微前端，并识别四类反模式。","frontmatter":{"title":"何时用，何时不用","description":"用五个信号判断是否该引入微前端，并识别四类反模式。"},"headers":[],"relativePath":"guide/when-to-use.md","filePath":"guide/when-to-use.md","lastUpdated":1792674288000}'),o={name:"guide/when-to-use.md"};function i(l,a,h,n,s,c){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="何时用-何时不用" tabindex="-1">何时用，何时不用 <a class="header-anchor" href="#何时用-何时不用" aria-label="Permalink to &quot;何时用，何时不用&quot;">​</a></h1><p>微前端是<strong>组织复杂度</strong>的解法，不是<strong>技术复杂度</strong>的解法。技术问题优先用技术解决：拆包、懒加载、缓存、Monorepo，往往比引入微前端便宜得多。</p><h2 id="五个-该用-的信号" tabindex="-1">五个“该用”的信号 <a class="header-anchor" href="#五个-该用-的信号" aria-label="Permalink to &quot;五个“该用”的信号&quot;">​</a></h2><h3 id="_1-多团队独立发布" tabindex="-1">1. 多团队独立发布 <a class="header-anchor" href="#_1-多团队独立发布" aria-label="Permalink to &quot;1. 多团队独立发布&quot;">​</a></h3><p>两个以上团队维护同一产品，每次发布都要一起回归、一起排队。微前端可以把发布解耦。</p><h3 id="_2-存在无法短期重写的老系统" tabindex="-1">2. 存在无法短期重写的老系统 <a class="header-anchor" href="#_2-存在无法短期重写的老系统" aria-label="Permalink to &quot;2. 存在无法短期重写的老系统&quot;">​</a></h3><p>老系统用 jQuery、AngularJS 或旧版 Vue，重写成本高。微前端可以让它和新系统共存，逐步替换。</p><h3 id="_3-技术栈差异是既定事实" tabindex="-1">3. 技术栈差异是既定事实 <a class="header-anchor" href="#_3-技术栈差异是既定事实" aria-label="Permalink to &quot;3. 技术栈差异是既定事实&quot;">​</a></h3><p>例如并购、历史遗留、不同业务线技术选型不同。强行统一会带来更大的迁移风险。</p><h3 id="_4-单仓构建已经明显变慢" tabindex="-1">4. 单仓构建已经明显变慢 <a class="header-anchor" href="#_4-单仓构建已经明显变慢" aria-label="Permalink to &quot;4. 单仓构建已经明显变慢&quot;">​</a></h3><p>构建时间、依赖冲突、发布影响面已经成为日常痛点。</p><h3 id="_5-需要按业务域独立演进" tabindex="-1">5. 需要按业务域独立演进 <a class="header-anchor" href="#_5-需要按业务域独立演进" aria-label="Permalink to &quot;5. 需要按业务域独立演进&quot;">​</a></h3><p>不同业务域迭代频率差异很大，例如交易高频、报表低频。独立部署能减少互相干扰。</p><h2 id="四个-别用-的信号" tabindex="-1">四个“别用”的信号 <a class="header-anchor" href="#四个-别用-的信号" aria-label="Permalink to &quot;四个“别用”的信号&quot;">​</a></h2><h3 id="_1-只有一个团队、一个发布节奏" tabindex="-1">1. 只有一个团队、一个发布节奏 <a class="header-anchor" href="#_1-只有一个团队、一个发布节奏" aria-label="Permalink to &quot;1. 只有一个团队、一个发布节奏&quot;">​</a></h3><p>此时微前端只会增加构建、部署、调试、监控的复杂度，收益接近于零。</p><h3 id="_2-只是想复用组件" tabindex="-1">2. 只是想复用组件 <a class="header-anchor" href="#_2-只是想复用组件" aria-label="Permalink to &quot;2. 只是想复用组件&quot;">​</a></h3><p>用组件库或 Monorepo 即可。微前端不是复用工具。</p><h3 id="_3-团队没有基建能力" tabindex="-1">3. 团队没有基建能力 <a class="header-anchor" href="#_3-团队没有基建能力" aria-label="Permalink to &quot;3. 团队没有基建能力&quot;">​</a></h3><p>没有统一的 CI、监控、日志、网关，微前端会把问题放大：版本不一致、资源 404、样式冲突都更难排查。</p><h3 id="_4-子应用之间需要高频共享状态" tabindex="-1">4. 子应用之间需要高频共享状态 <a class="header-anchor" href="#_4-子应用之间需要高频共享状态" aria-label="Permalink to &quot;4. 子应用之间需要高频共享状态&quot;">​</a></h3><p>如果两个模块每秒钟都在同步数据，说明它们本就不该拆开。强行拆分会制造大量通信代码。</p><h2 id="四类常见反模式" tabindex="-1">四类常见反模式 <a class="header-anchor" href="#四类常见反模式" aria-label="Permalink to &quot;四类常见反模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>反模式</th><th>表现</th><th>后果</th></tr></thead><tbody><tr><td>为拆而拆</td><td>按页面数量均分给不同团队</td><td>边界与业务不一致，联调成本更高</td></tr><tr><td>只集成不治理</td><td>能加载就行，没有版本与监控</td><td>上线后故障定位困难</td></tr><tr><td>共享过度</td><td>子应用直接 import 主应用源码</td><td>独立部署名存实亡</td></tr><tr><td>隔离缺失</td><td>全局变量与样式随意覆盖</td><td>一个子应用出错，全站受影响</td></tr></tbody></table><h2 id="一张判断清单" tabindex="-1">一张判断清单 <a class="header-anchor" href="#一张判断清单" aria-label="Permalink to &quot;一张判断清单&quot;">​</a></h2><p>在立项前，逐条回答：</p><ul><li>[ ] 是否有两个以上团队需要独立发布？</li><li>[ ] 是否存在短期无法重写的老系统？</li><li>[ ] 是否已有统一网关、CI、监控？</li><li>[ ] 是否接受子应用独立技术栈带来的维护成本？</li><li>[ ] 是否能在 4 周内做出一个可回滚的试点？</li><li>[ ] 是否有明确的子应用边界与接口契约？</li><li>[ ] 是否准备好版本矩阵与灰度方案？</li></ul><p>7 条中少于 4 条为“是”，建议先不引入微前端。</p><h2 id="如果决定要做-先做试点" tabindex="-1">如果决定要做，先做试点 <a class="header-anchor" href="#如果决定要做-先做试点" aria-label="Permalink to &quot;如果决定要做，先做试点&quot;">​</a></h2><p>推荐路径：</p><ol><li>选一个<strong>边界清晰、影响面小</strong>的业务域。</li><li>保留主应用，接入一个子应用。</li><li>打通 CI、部署、监控、回滚。</li><li>运行一个迭代周期，收集问题。</li><li>再决定是否扩大范围。</li></ol><p>不要一次性把核心交易链路全部微前端化。先从边缘业务开始，把基建跑顺。</p><h2 id="成本要提前算" tabindex="-1">成本要提前算 <a class="header-anchor" href="#成本要提前算" aria-label="Permalink to &quot;成本要提前算&quot;">​</a></h2><table tabindex="0"><thead><tr><th>成本项</th><th>说明</th></tr></thead><tbody><tr><td>基建</td><td>基座、脚手架、CI、CDN、监控</td></tr><tr><td>规范</td><td>路由、通信、样式、版本、发布</td></tr><tr><td>调试</td><td>跨应用排查、日志关联、Source Map</td></tr><tr><td>组织</td><td>边界划分、接口评审、值班机制</td></tr></tbody></table><p>微前端的收益是<strong>组织效率</strong>，成本是<strong>工程复杂度</strong>。只有当前者明显大于后者，这笔账才算得过来。</p><p>继续阅读：<a href="/micro-frontend-docs/guide/evolution">技术演进</a> 或直接看 <a href="/micro-frontend-docs/guide/decision-tree">选型决策树</a>。</p>',36)])])}const b=t(o,[["render",i]]);export{p as __pageData,b as default};
